import { action, addPagination, choiceOption, collect, collectFreigabeStatus, parseNonEmpty, pruneUndefined, renderJson, renderRaw, } from "../shared.js";
import { DokumentartValues, SteckbriefSucheInValues, XdfVersionValues, DatenfelderSearchOrderValues, } from "@maschinenlesbar.org/fim-portal-client/internal/enums";
export function registerDocumentProfileCommands(program, deps) {
    const dp = program
        .command("document-profiles")
        .description("Dokumentsteckbriefe (document profiles)");
    const search = dp
        .command("search")
        .description("Search/filter document profiles")
        .option("--name <name>", "filter by name", parseNonEmpty)
        .option("--nummernkreis <nk>", "filter by Nummernkreis (repeatable, prefix match)", collect)
        .option("--freigabe-status <code>", "filter by Freigabestatus 1..8 (repeatable)", collectFreigabeStatus)
        .option("--status-gesetzt-durch <who>", "filter by status author", parseNonEmpty)
        .option("--status-gesetzt-seit <date>", "status set on/after this date", parseNonEmpty)
        .option("--status-gesetzt-bis <date>", "status set on/before this date", parseNonEmpty)
        .option("--bezeichnung <text>", "filter by Bezeichnung", parseNonEmpty)
        .addOption(choiceOption("--dokumentart <code>", "filter by Dokumentart", DokumentartValues))
        .option("--bezug <text>", "filter by Bezug", parseNonEmpty)
        .option("--fts-query <q>", "full-text search query", parseNonEmpty)
        .addOption(choiceOption("--suche-nur-in <module>", "restrict full-text search to a module", SteckbriefSucheInValues))
        .option("--versionshinweis <text>", "filter by Versionshinweis", parseNonEmpty)
        .option("--updated-since <iso>", "filter by last-update timestamp (ISO-8601)", parseNonEmpty)
        .addOption(choiceOption("--xdf-version <v>", "filter by XDatenfelder version", XdfVersionValues))
        .option("--stichwort <text>", "filter by Stichwort (XDF3 only)", parseNonEmpty)
        .option("--is-latest", "only the latest version of each kind")
        .addOption(choiceOption("--order-by <order>", "result order", DatenfelderSearchOrderValues));
    addPagination(search).action(action(deps, async ({ client, global, opts }) => {
        const params = pruneUndefined({
            name: opts["name"],
            nummernkreis: opts["nummernkreis"],
            freigabe_status: opts["freigabeStatus"],
            status_gesetzt_durch: opts["statusGesetztDurch"],
            status_gesetzt_seit: opts["statusGesetztSeit"],
            status_gesetzt_bis: opts["statusGesetztBis"],
            bezeichnung: opts["bezeichnung"],
            dokumentart: opts["dokumentart"],
            bezug: opts["bezug"],
            fts_query: opts["ftsQuery"],
            suche_nur_in: opts["sucheNurIn"],
            // The API spells this one parameter with a capital V; a lowercase name is ignored.
            Versionshinweis: opts["versionshinweis"],
            updated_since: opts["updatedSince"],
            xdf_version: opts["xdfVersion"],
            stichwort: opts["stichwort"],
            is_latest: opts["isLatest"],
            order_by: opts["orderBy"],
            offset: opts["offset"],
            limit: opts["limit"],
        });
        renderJson(deps, global, await client.documentProfiles.search(params));
    }));
    dp.command("versions")
        .argument("<fimId>", "FIM id (e.g. S07000009)", parseNonEmpty)
        .description("List all versions of a document profile")
        .action(action(deps, async ({ client, global }, [fimId]) => {
        renderJson(deps, global, await client.documentProfiles.versions(fimId));
    }));
    dp.command("get")
        .argument("<fimId>", "FIM id (e.g. S07000009)", parseNonEmpty)
        .argument("[fimVersion]", "FIM version (default: latest)", parseNonEmpty)
        .description("Get a single document profile (version defaults to 'latest')")
        .action(action(deps, async ({ client, global }, [fimId, fimVersion]) => {
        renderJson(deps, global, await client.documentProfiles.get(fimId, fimVersion ?? "latest"));
    }));
    dp.command("xdf")
        .argument("<fimId>", "FIM id (e.g. S07000009)", parseNonEmpty)
        .argument("[fimVersion]", "FIM version (default: latest)", parseNonEmpty)
        .description("Download the XDatenfelder XML for a document profile")
        .action(action(deps, async ({ client, global }, [fimId, fimVersion]) => {
        await renderRaw(deps, global, await client.documentProfiles.downloadXdf(fimId, fimVersion ?? "latest"));
    }));
}
